import { Component, signal } from '@angular/core';

@Component({
  selector: 'app-avatar',
  template: `
    <img [src]="photoUrl()" [alt]="'Photo of ' + name()" width="64" height="64">
    <button
      [disabled]="saving()"
      [class.busy]="saving()"
      [style.opacity]="saving() ? 0.5 : 1"
      [attr.aria-label]="'Save ' + name()">
      Save
    </button>
  `,
})
export class Avatar {
  readonly name = signal('Ada');
  readonly photoUrl = signal('/assets/ada.png');
  readonly saving = signal(true);
}

import { Component, signal } from '@angular/core';

@Component({
  selector: 'app-search',
  template: `
    <input #box (input)="query.set(box.value)" (keydown.enter)="search()" placeholder="Search">
    <button (click)="search()">Go</button>
    <p>Typing: {{ query() }}</p>
    <p>{{ message() }}</p>
  `,
})
export class Search {
  readonly query = signal('');
  readonly message = signal('');

  search(): void {
    this.message.set(`Searching for "${this.query()}"`);
  }
}

import { Component, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-nickname',
  imports: [FormsModule],
  template: `
    <label>Nickname <input [(ngModel)]="nickname"></label>
    <p>Hello, {{ nickname() }}!</p>
  `,
})
export class Nickname {
  readonly nickname = signal('ada');
}
